"""Standalone interactive sky explorer for notebook-derived Cartesian vectors."""
from __future__ import annotations

import json
from pathlib import Path
from typing import Any


def write_sky_explorer(notebook: dict[str, Any], output: str | Path) -> Path:
    target = Path(output)
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(render_sky_explorer(notebook), encoding="utf-8")
    return target


def render_sky_explorer(notebook: dict[str, Any]) -> str:
    candidate = next((item for item in notebook.get("representations", {}).values() if item.get("derived_data_id")), None)
    if not candidate:
        raise ValueError("notebook has no representation with derived data")
    data = notebook.get("derived_data", {}).get(candidate["derived_data_id"])
    if not data or not data.get("rows"):
        raise ValueError("notebook has no explorable derived vector rows")
    rows = json.dumps(data["rows"]).replace("</", "<\\/")
    title = _escape(str(notebook.get("title", "Sky explorer")))
    return f"""<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><style>
:root{{--paper:#f5f5f5;--ink:#2d3142;--muted:#4f5d75;--soft:#7a8399;--accent:#eb6c36;--rule:rgba(45,49,66,.16)}}*{{box-sizing:border-box}}body{{margin:0;background:var(--paper);color:var(--ink);font:16px system-ui,sans-serif}}main{{max-width:1100px;margin:32px auto;padding:0 24px}}h1{{font:400 40px Georgia,serif;margin:0 0 8px}}p{{color:var(--muted);max-width:760px}}.layout{{display:grid;grid-template-columns:1fr 260px;gap:32px;align-items:start;margin-top:28px}}.plot,.readout{{background:#fff;border:1px solid var(--rule);padding:16px}}svg{{display:block;width:100%;aspect-ratio:1;background:var(--paper)}}.eyebrow,.meta{{font:11px ui-monospace,monospace;letter-spacing:.08em;color:var(--soft)}}.controls{{border-top:1px solid var(--rule);padding-top:16px}}label{{display:block;font-size:13px;font-weight:600;margin:0 0 20px}}input{{width:100%;accent-color:var(--accent)}}.readout{{margin-top:20px;min-height:138px;font-size:14px}}.readout strong{{display:block;margin-bottom:8px}}.readout code{{color:var(--muted);font-size:12px}}button{{background:transparent;border:1px solid var(--ink);padding:8px 12px;font:inherit;cursor:pointer;margin:0 8px 8px 0}}button:hover{{background:var(--accent);border-color:var(--accent);color:#fff}}@media(max-width:720px){{.layout{{grid-template-columns:1fr}}h1{{font-size:32px}}}}</style></head><body><main><div class="eyebrow">ICRS UNIT-SPHERE EXPLORER · DERIVED DATA</div><h1>{title}</h1><p>Rotate the Cartesian representation. Click two objects to measure their great-circle separation; the calculation uses the original 3D vectors, not the projected screen distance. Error halos appear only for explicit degree-based catalog uncertainty.</p><div class="layout"><section class="plot"><svg id="sky" viewBox="0 0 720 720" role="img" aria-label="Interactive rotated ICRS unit sphere"></svg></section><aside><div class="controls"><label>Longitude rotation <output id="lonOut">0°</output><input id="lon" type="range" min="0" max="360" value="0"></label><label>Latitude rotation <output id="latOut">0°</output><input id="lat" type="range" min="-90" max="90" value="0"></label><button id="reset">Reset view</button><button id="clear">Clear measurement</button></div><div class="readout" id="readout"><strong>Select two objects</strong><span>First click sets A; second click measures A → B.</span></div></aside></div><p class="meta">Representation: {_escape(candidate.get('title', 'Unit sphere'))} · {len(data['rows'])} derived vectors · x/y plot is an orthographic projection.</p></main><script>const rows={rows},svg=document.querySelector('#sky'),lon=document.querySelector('#lon'),lat=document.querySelector('#lat'),readout=document.querySelector('#readout'),ns='http://www.w3.org/2000/svg';let selected=[];function el(tag,attrs={{}}){{const n=document.createElementNS(ns,tag);for(const[k,v]of Object.entries(attrs))n.setAttribute(k,v);return n}}function project(p){{const a=Number(lon.value)*Math.PI/180,b=Number(lat.value)*Math.PI/180,x1=Math.cos(a)*p.x-Math.sin(a)*p.y,y1=Math.sin(a)*p.x+Math.cos(a)*p.y;return{{x:x1,y:Math.cos(b)*y1-Math.sin(b)*p.z,z:Math.sin(b)*y1+Math.cos(b)*p.z}}}}function separation(a,b){{const dot=(a.x*b.x+a.y*b.y+a.z*b.z)/Math.hypot(a.x,a.y,a.z)/Math.hypot(b.x,b.y,b.z);return Math.acos(Math.max(-1,Math.min(1,dot)))*180/Math.PI}}function render(){{svg.replaceChildren();svg.append(el('circle',{{cx:360,cy:360,r:300,fill:'#fff',stroke:'#2d3142','stroke-width':1}}));svg.append(el('line',{{x1:60,y1:360,x2:660,y2:360,stroke:'rgba(45,49,66,.14)'}}));svg.append(el('line',{{x1:360,y1:60,x2:360,y2:660,stroke:'rgba(45,49,66,.14)'}}));const points=rows.map(item=>[item,project(item)]);if(selected.length===2){{const a=points.find(([item])=>item===selected[0])[1],b=points.find(([item])=>item===selected[1])[1];svg.append(el('line',{{x1:360+a.x*300,y1:360-a.y*300,x2:360+b.x*300,y2:360-b.y*300,stroke:'#eb6c36','stroke-width':2}}))}}for(const[item,p]of points){{const front=p.z>=0,x=360+p.x*300,y=360-p.y*300,uncertainty=Number(item.uncertainty_deg||0),halo=Math.min(48,uncertainty*12);if(halo)svg.append(el('circle',{{cx:x,cy:y,r:halo,fill:'rgba(235,108,54,.08)',stroke:'rgba(235,108,54,.55)','stroke-width':1,'stroke-dasharray':'4,3'}}));const chosen=selected.includes(item),circle=el('circle',{{cx:x,cy:y,r:chosen?8:(front?6:4),fill:chosen?'rgba(235,108,54,.22)':(front?'rgba(79,93,117,.35)':'rgba(79,93,117,.10)'),stroke:chosen?'#eb6c36':(front?'#4f5d75':'rgba(79,93,117,.35)'),'stroke-width':chosen?2:1,tabindex:0}});circle.addEventListener('click',()=>select(item));circle.addEventListener('keydown',e=>{{if(e.key==='Enter')select(item)}});svg.append(circle)}}}}function select(item){{if(selected.includes(item))return;if(selected.length===2)selected=[];selected.push(item);if(selected.length===1)readout.innerHTML=`<strong>A: ${{escapeHtml(String(item.id))}}</strong><code>RA ${{item.ra_deg}}° · Dec ${{item.dec_deg}}°</code><br><span>Select B to measure great-circle separation.</span>`;else{{const[a,b]=selected,angle=separation(a,b),combined=Math.hypot(Number(a.uncertainty_deg||0),Number(b.uncertainty_deg||0));readout.innerHTML=`<strong>A: ${{escapeHtml(String(a.id))}} → B: ${{escapeHtml(String(b.id))}}</strong><code>great-circle separation: ${{angle.toFixed(6)}}°</code><br><code>3D vector calculation; projected line is only a visual guide</code>${{combined?`<br><code>combined listed uncertainty: ${{combined.toFixed(6)}}°</code>`:''}}`}}render()}}function escapeHtml(v){{const d=document.createElement('div');d.textContent=v;return d.innerHTML}}function update(){{document.querySelector('#lonOut').value=lon.value+'°';document.querySelector('#latOut').value=lat.value+'°';render()}}lon.oninput=update;lat.oninput=update;document.querySelector('#reset').onclick=()=>{{lon.value=0;lat.value=0;update()}};document.querySelector('#clear').onclick=()=>{{selected=[];readout.innerHTML='<strong>Select two objects</strong><span>First click sets A; second click measures A → B.</span>';render()}};update();</script></body></html>"""


def _escape(value: str) -> str:
    return value.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace('"', "&quot;")
